"""JSI message implementations."""

import collections
import typing

from jsilib import _utils
from jsilib.aio.api import ByteStream, IStream

from .interface import IJSIMessage

__all__ = export = _utils.ExportList()


@export
class JSIStreamMessage(IJSIMessage):
    """Wraps given :class:`IStream` object with a :class:`IJSIMessage`
    interface.

    :param stream:
        The stream to be wrapped

    :param size:
        The size (in bytes) of a resulting message
    """

    def __init__(self, stream: IStream, size: int):
        self._stream = stream
        self._size = size
        self._bytes_left = size

    def is_closed(self) -> bool:
        return self._stream.is_closed()

    async def close(self):
        await self._stream.close()

    def size(self) -> int:
        return self._size

    def bytes_left(self) -> int:
        return self._bytes_left

    async def read(self, count: int) -> bytes:
        data = await self._stream.read(count)
        self._bytes_left -= len(data)
        return data


@export
class JSIBytesMessage(JSIStreamMessage):
    """Wraps given bytes with a :class:`IMessage` interface.

    Useful for constructing short messages with an already known payload.

    :param data:
        Binary message content
    """

    def __init__(self, data: bytes):
        super().__init__(ByteStream(data), len(data))


@export
class JSIConcatenatedMessage(IJSIMessage):
    """A message that is a concatenation of one or more other messages.

    The order in which parts are given determine the content of a resulting
    message. The size of a resulting message is a total size of all parts.

    :param parts:
        Parts from which this message is made of
    """

    def __init__(self, parts: typing.Iterable[IJSIMessage]):
        self._closed = False
        self._remaining_parts = collections.deque(parts)
        self._size = 0
        for part in self._remaining_parts:
            self._size += part.size()
        self._bytes_left = self._size

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        self._closed = True
        for payload in self._remaining_parts:
            await payload.close()

    def size(self) -> int:
        return self._size

    def bytes_left(self) -> int:
        return self._bytes_left

    async def read(self, count: int) -> bytes:
        part = self._remaining_parts[0]
        count = min(part.bytes_left(), count)
        data = await part.read(count)
        if part.bytes_left() == 0:
            self._remaining_parts.popleft()
        self._bytes_left -= len(data)
        return data
